import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Summit Telemetry and Ceph MGR","description":"","frontmatter":{"title":"Ceph Developer Summit Telemetry and Ceph MGR","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","分布式存储","遥测","自管理","MGR"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_Telemetry_and_Ceph_MGR.md","filePath":"posts/2025/Ceph_Developer_Summit_Telemetry_and_Ceph_MGR.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Ceph_Developer_Summit_Telemetry_and_Ceph_MGR.md"};function o(i,e,s,h,u,g){return l(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="ceph-开发者峰会-遥测与-ceph-mgr" tabindex="-1">Ceph 开发者峰会：遥测与 Ceph MGR <a class="header-anchor" href="#ceph-开发者峰会-遥测与-ceph-mgr" aria-label="Permalink to &quot;Ceph 开发者峰会：遥测与 Ceph MGR&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1"><strong>会议基本信息</strong> <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;**会议基本信息**&quot;">​</a></h4><ul><li><strong>会议主题</strong>：Ceph 自管理（Self-Manager）与遥测（Telemetry）讨论</li><li><strong>时间</strong>：近期开发周期内</li><li><strong>参会人员</strong>：Anthony、Junior、Radic、Ital、Nan、Jer、Laura 等（部分成员未全程参与）</li></ul><h4 id="讨论议题与关键细节" tabindex="-1"><strong>讨论议题与关键细节</strong> <a class="header-anchor" href="#讨论议题与关键细节" aria-label="Permalink to &quot;**讨论议题与关键细节**&quot;">​</a></h4><h5 id="_1-遥测-telemetry-功能改进" tabindex="-1">1. 遥测（Telemetry）功能改进 <a class="header-anchor" href="#_1-遥测-telemetry-功能改进" aria-label="Permalink to &quot;1. 遥测（Telemetry）功能改进&quot;">​</a></h5><ul><li><strong>Bluestore 数据收集</strong>： <ul><li>Tentacle 版本中未实现对 Bluestore 默认分配器的数据收集，需后续与 Adam/Egore 确认需求并可能回迁至稳定分支。</li><li>用户需重新启用以接收新增的遥测数据。</li></ul></li><li><strong>RGW 多站点（RGW Multisite）信息</strong>： <ul><li>需 RGW 团队支持添加相关指标，当前无团队成员在场，需后续跟进。</li></ul></li><li><strong>Crimson OSD 性能计数器支持</strong>： <ul><li>Crimson 使用独立的 Seastar 性能计数器基础设施，与经典 OSD 不同，需进一步讨论如何兼容 Python 模块暴露。</li></ul></li></ul><h5 id="_2-自管理-self-manager-功能优化" tabindex="-1">2. 自管理（Self-Manager）功能优化 <a class="header-anchor" href="#_2-自管理-self-manager-功能优化" aria-label="Permalink to &quot;2. 自管理（Self-Manager）功能优化&quot;">​</a></h5><ul><li><strong>TTL Cache 改进</strong>： <ul><li>当前 TTL Cache 默认禁用，计划改为 Manager Cache，解决内存/CPU 消耗高及数据陈旧问题。</li><li>已有草案 PR，目标纳入 Umbrella 版本。</li></ul></li><li><strong>Manager Stats 周期自动调节（Autotuning）</strong>： <ul><li>根据 OSD 队列负载动态调整统计周期，避免单 MGR 实例过载。</li></ul></li><li><strong>模块加载优化（Module Loading Improvements）</strong>： <ul><li>Laura 的 PR 改进模块加载顺序，已接近完成，将合入 Tentacle 版本。</li></ul></li><li><strong>模块性能计数器（Perf Counters for Modules）</strong>： <ul><li>新增指标包括 CPU、内存占用及命令平均耗时，帮助识别资源密集型模块。</li><li>通过 C++ 层统计，需注意共享资源（如缓存）的归属问题。</li></ul></li></ul><h5 id="_3-集群内容遥测-cluster-content-telemetry" tabindex="-1">3. 集群内容遥测（Cluster Content Telemetry） <a class="header-anchor" href="#_3-集群内容遥测-cluster-content-telemetry" aria-label="Permalink to &quot;3. 集群内容遥测（Cluster Content Telemetry）&quot;">​</a></h5><ul><li><strong>低优先级</strong>：因实现复杂且可能显著影响性能，Umbrella 版本暂不包含。</li><li>未来可能设计独立进程爬取集群数据，供遥测调用。</li></ul><h5 id="_4-crush-规则与设备类优化" tabindex="-1">4. CRUSH 规则与设备类优化 <a class="header-anchor" href="#_4-crush-规则与设备类优化" aria-label="Permalink to &quot;4. CRUSH 规则与设备类优化&quot;">​</a></h5><ul><li><strong>问题背景</strong>：默认 CRUSH 规则与设备专用规则重叠时，Autoscaler 无法准确计算 PG 目标值。</li><li><strong>解决方案</strong>：提供更明确的健康警告，研究自动分配管理器池至设备类规则的启发式方法。</li></ul><h5 id="_5-manager-测试覆盖率提升" tabindex="-1">5. Manager 测试覆盖率提升 <a class="header-anchor" href="#_5-manager-测试覆盖率提升" aria-label="Permalink to &quot;5. Manager 测试覆盖率提升&quot;">​</a></h5><ul><li><strong>现状</strong>：单元测试不足，尤其是 API 调用和模块实际场景测试。</li><li><strong>计划</strong>：由 Nan 牵头补充测试用例，重点覆盖内存泄漏、进程崩溃等常见问题。</li></ul><h4 id="决议事项" tabindex="-1"><strong>决议事项</strong> <a class="header-anchor" href="#决议事项" aria-label="Permalink to &quot;**决议事项**&quot;">​</a></h4><ol><li><strong>Telemetry</strong>：跟进 Bluestore 和 RGW Multisite 指标收集。</li><li><strong>Manager Cache</strong>：合并 TTL Cache 改进 PR 至 Umbrella 版本。</li><li><strong>Autotuning &amp; Perf Counters</strong>：优先实现 Manager Stats 自动调节和模块性能计数器。</li><li><strong>CRUSH 规则</strong>：优化用户体验（健康警告 + 文档），暂不自动迁移管理器池。</li><li><strong>测试</strong>：全员协作补充 Manager 测试用例，提升稳定性验证。</li></ol><h4 id="后续行动计划" tabindex="-1"><strong>后续行动计划</strong> <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;**后续行动计划**&quot;">​</a></h4><p>| 任务 | 负责人 | 时间线 | ||--|--| | Bluestore 数据收集需求确认 | Anthony/Adam/Egore | Tentacle 版本后 | | Manager Cache PR 审核与合并 | Ital/团队 | Umbrella 开发周期内 | | Autotuning 逻辑实现 | Brad/Radic | 3 月前 | | CRUSH 规则警告增强 | Jer | Umbrella 发布前 | | 模块测试用例补充 | Nan/Stephen | 持续进行 |</p><h4 id="遗留问题与待跟进" tabindex="-1"><strong>遗留问题与待跟进</strong> <a class="header-anchor" href="#遗留问题与待跟进" aria-label="Permalink to &quot;**遗留问题与待跟进**&quot;">​</a></h4><ul><li>Crimson OSD 性能计数器与 Python 模块的集成路径。</li><li>管理器池是否包含设备健康指标。</li><li>集群内容遥测的轻量级设计方案。</li></ul><h4 id="下次会议" tabindex="-1"><strong>下次会议</strong> <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;**下次会议**&quot;">​</a></h4><p>RADOS 相关讨论（周四），可能涉及 Manager 交叉议题。</p>',22)])])}const c=a(n,[["render",o]]);export{d as __pageData,c as default};
